import {bindTouch} from './touch.mjs';
import {chapters,statsDefault,move} from './story.mjs';
import {loadArt,person,scene,marker,ball,label} from './render.mjs';
import {Music} from './audio.mjs';
const $=s=>document.querySelector(s),canvas=$('#world'),g=canvas.getContext('2d'),music=new Music(),keys=new Set();
const touchKeys=new Set(),held=k=>keys.has(k)||touchKeys.has(k);
const mobile=()=>window.matchMedia?.('(pointer: coarse)').matches||window.innerWidth<=720;
function deviceText(s){return mobile()?s.replaceAll('Space','대화·조사 버튼').replaceAll(' → X',' → 슛 버튼').replaceAll(' → Z',' → 패스 버튼').replaceAll('슈팅은 X, 패스는 Z','슈팅은 슛 버튼, 패스는 패스 버튼'):s}

let art,index=0,step=0,p={x:400,y:350,dir:0,kind:'muho',name:'김무호'},npcs=[],stats=statsDefault(),task=null,phase='title',paused=false,clock=0,last=0,walkTime=0,stamina=100,runTime=45,turf=0,zoom=1,flash=0,shot=null,particles=[],tween=null,resolveSay=null,generation=0,workStart=0,hubRound=0,history=[],noticeUntil=0;
function notify(s){$('#notice').textContent=deviceText(s);noticeUntil=clock+3}
function refresh(){const c=chapters[index];$('#chapter').textContent=`${index===8?'PART 2':'PART 1'} · ${c.name}`;$('#age').textContent=index>=6&&index<8?'성인 · 공장 근로자':index===8?'14세 · 인생 2회차':'14세 · 축구부';$('#stats').innerHTML=Object.entries(stats).map(([k,v])=>`<label>${k} <span>${v}</span><i><em style="width:${v}%"></em></i></label>`).join('');$('#chapters').innerHTML=chapters.map((c,i)=>`<li class="${i===index?'active':i<index?'done':''}">${c.name}</li>`).join('');$('#goal').textContent=task?.label||(index===8?'감독에게 다가가 Space로 훈련을 시작하세요.':'이야기를 듣고 있습니다.');$('#caption').textContent=task?.label||(index===8?'자유 훈련 · 감독 / 아버지 / 동료와 대화':'Space · 대화 계속');$('#log').textContent=history.slice(-5).join(' · ');$('#caption').textContent=deviceText($('#caption').textContent);$('#mobile-status').textContent=deviceText(task?.label||'이야기 진행 중 · 대화창의 계속 버튼을 누르세요.');$('#next').textContent=mobile()?'계속 ▼':'Space · 계속 ▼'}
function wait(seconds){const token=generation,target=clock+seconds;return new Promise((resolve,reject)=>{function tick(){if(token!==generation){reject(new Error('cancelled'));return}if(clock>=target)resolve();else requestAnimationFrame(tick)}tick()})}
function guard(fn){Promise.resolve().then(fn).catch(e=>{if(e.message!=='cancelled'){console.error(e);notify('진행 오류가 발생했습니다. 메뉴에서 챕터를 다시 시작할 수 있습니다.');phase='play'}})}
async function say(lines){for(const [who,emotion,text]of lines){phase='dialog';$('#dialog').hidden=false;$('#answers').replaceChildren();$('#next').hidden=false;$('#speaker').textContent=who+' · '+emotion;$('#line').textContent=deviceText(text);const pg=$('#portrait').getContext('2d');pg.clearRect(0,0,80,80);let kind=who==='김무호'?p.kind:who==='계민킴'?0:who.includes('선생')?1:who==='친구'?2:who==='선배'?4:3;pg.save();pg.scale(1.5,1.5);person(pg,art,{x:27,y:51,kind,dir:0},0);pg.restore();music.sfx('talk');await new Promise(r=>resolveSay=r);resolveSay=null}$('#dialog').hidden=true;phase='busy'}
function next(){if(resolveSay){const r=resolveSay;resolveSay=null;r()}}
async function card(text,seconds=2){$('#card').textContent=text;$('#card').hidden=false;await wait(seconds);$('#card').hidden=true}
async function animate(actor,x,y,duration=1){const x0=actor.x,y0=actor.y,start=clock;actor.walk=true;while(clock-start<duration){const k=Math.min(1,(clock-start)/duration);actor.x=x0+(x-x0)*k;actor.y=y0+(y-y0)*k;actor.dir=Math.abs(x-x0)>Math.abs(y-y0)?(x>x0?2:1):(y>y0?0:3);await wait(.02)}actor.x=x;actor.y=y;actor.walk=false}
async function playMemory(data){
 phase='video';keys.clear();touchKeys.clear();const overlay=$('#memory'),video=$('#memory-video'),play=$('#memory-play');
 $('#memory-title').textContent=data.title;$('#memory-caption').textContent=data.caption;$('#memory-hint').textContent='';overlay.hidden=false;
 const gain=music.g?.gain,volume=gain?.value;if(gain)gain.value=0;
 await new Promise(resolve=>{
  let done=false;const finish=()=>{if(done)return;done=true;video.pause();video.onended=null;video.onerror=null;overlay.hidden=true;if(gain)gain.value=volume;resolve()};
  const start=()=>{play.hidden=true;video.play().catch(()=>{if(done)return;play.hidden=false;$('#memory-hint').textContent='재생 버튼을 누르면 영상이 시작됩니다.'})};
  video.onended=finish;video.onerror=()=>{play.hidden=true;$('#memory-hint').textContent='영상을 불러오지 못했습니다. 건너뛰고 계속할 수 있습니다.'};
  $('#memory-skip').onclick=finish;play.onclick=start;video.src=data.src;video.muted=!music.on;start();
 });
 phase='busy';await card(data.after,2);
}
async function loadChapter(n){generation++;index=n;step=0;p={x:chapters[n].start[0],y:chapters[n].start[1],dir:0,kind:n>=6&&n<8?5:'muho',name:'김무호',walk:false};npcs=structuredClone(chapters[n].npcs);task=null;phase='busy';shot=null;turf=0;zoom=1;flash=0;stamina=100;runTime=45;keys.clear();touchKeys.clear();$('#dialog').hidden=true;$('#card').hidden=true;music.set(chapters[n].music);refresh();await card(`${n===8?'PART 2':'CHAPTER '+(n+1)}\n${chapters[n].name}`,1.8);if(chapters[n].memory)await playMemory(chapters[n].memory);await say(chapters[n].intro);setTask();storeSave(false)}
function setTask(){task=chapters[index].tasks[step]||null;phase='play';if(index===8&&!task)task={type:'hub',x:260,y:220,label:'감독 ◆에게 다가가 Space · 첫 자유 훈련'};refresh()}
async function finish(){const done=task;task=null;phase='busy';p.walk=false;keys.clear();touchKeys.clear();if(['shoot','pass'].includes(done.type)){music.sfx('hit');shot={x:p.x,y:p.y+8,fromX:p.x,fromY:p.y+8,toX:done.effect==='miss'?530:done.type==='pass'?630:400,toY:done.type==='pass'?320:168,start:clock};await wait(.7);shot=null}if(done.effect==='goal'){zoom=1.16;music.sfx('goal');particles=Array.from({length:70},(_,i)=>({x:150+(i*97)%500,y:160+(i*41)%200,color:['#ffe091','#a0dcd6','#ce98de'][i%3]}));await card('GOAL!\n프레스토컵, 마지막 순간의 기적',1.7);await animate(npcs[0],480,215,.8)}if(done.effect==='steal'){await animate(npcs.find(n=>n.id==='rival'),p.x+25,p.y,.5);notify('공을 빼앗겼다 · 프롤로그의 정해진 과거');music.sfx('hit')}if(done.effect==='teacher'){music.sfx('hit');await animate(npcs[0],p.x+24,p.y,.6);g.fillStyle='#adba9e';g.fillRect(p.x+15,p.y,5,2)}if(done.lines.length)await say(done.lines);zoom=1;particles=[];
 if(done.effect==='turf'){music.sfx('goal');$('#notice').textContent='계민킴, 축구장 잔디 설치비 3억 원 지원!';const start=clock;while(clock-start<2.5){turf=Math.min(1,(clock-start)/2.5);await wait(.03)}turf=1;await wait(.6);music.set(6)}
 if(done.effect==='gather'){await Promise.all(npcs.filter(n=>n.kind===2).map((n,i)=>animate(n,p.x+(i?40:-40),p.y+20,.7)));zoom=1.12;await wait(.6);zoom=1}
 if(done.effect==='bag'){notify('검은 봉지에 담긴 건 쓰레기와 부당한 기대였다.');await animate(p,430,225,.6)}
 if(done.effect==='teacher'){await Promise.all([animate(p,625,270,1.4),animate(npcs[0],650,260,1.4)])}
 if(done.type==='device'){await chooseDevice();return}
 if(index===8){const key=done.type==='shoot'?'슈팅':done.type==='pass'?'패스':'드리블';stats[key]=Math.min(100,stats[key]+5);stats['감독 신뢰']=Math.min(100,stats['감독 신뢰']+3);hubRound++;history.push(key+' +5');if(hubRound%3===0){await say([['감독','인정','좋아. 드리블, 패스, 슈팅을 모두 해냈다. 이번에는 기본부터 쌓는 거다.'],['김무호','희망','이번 생에는 남의 기대가 아니라, 내 실력으로 뛰겠어.']]);notify('첫 자유 훈련 완료 · 계속 연습하거나 NPC와 대화할 수 있습니다.')}task={type:'hub',x:260,y:220,label:'감독 ◆ · 다음 훈련 / 아버지와 동료 대화'};phase='play';refresh();storeSave(false);return}
 history.push(chapters[index].name+' · 목표 완료');step++;if(step>=chapters[index].tasks.length){await card(chapters[index].outro,2.2);await loadChapter(index+1)}else setTask()}
async function chooseDevice(){phase='choice';$('#dialog').hidden=false;$('#speaker').textContent='시간 장치 · 운명의 선택';$('#line').textContent='14살의 그날로 돌아가시겠습니까?';$('#next').hidden=true;$('#answers').replaceChildren();for(const [title,yes]of [['예 · 다시 시작한다',true],['아니오 · 일을 계속한다',false]]){const b=document.createElement('button');b.textContent=title;b.onclick=()=>guard(async()=>{$('#dialog').hidden=true;$('#answers').replaceChildren();phase='busy';if(!yes){await say([['김무호','망설임','아직은... 마음의 준비가 안 됐어. 작업을 더 하다가 돌아오자.']]);task={type:'returnWork',x:250,y:270,label:'작업대 ◆에서 Space · 이후 장치로 다시 돌아올 수 있음'};phase='play';refresh();return}music.set(7);for(let n=5;n>0;n--){music.sfx('rewind');await card(String(n),.65)}flash=1;await wait(.25);flash=0;for(const m of ['factory','corridor','mountain','dirt','field','stadium']){tween=m;await wait(.3)}tween=null;await card('김무호, 인생 2회차 시작.',2);await loadChapter(8)});$('#answers').append(b)}}
function action(key){if(paused||phase==='title')return;if(phase==='choice'){const choices=Array.from($('#answers').children);if(key==='arrowleft'||key==='arrowright'){const selected=choices.indexOf(document.activeElement);choices[(selected+1)%choices.length]?.focus()}if(key==='Enter'&&!choices.includes(document.activeElement))choices[0]?.click();return}if(phase==='dialog'){if(key===' '||key==='Enter')next();return}if(phase==='work'){if(key===' '){const v=(Math.sin((clock-workStart)*3)+1)/2;if(v>.35&&v<.75){guard(finish)}else{music.sfx('hit');notify('다시 시도 · 바늘이 초록 구간에 오면 Space')}}return}if(phase!=='play')return;
 if(index===8&&key===' '){const near=npcs.find(n=>Math.hypot(p.x-n.x,p.y-n.y)<60);if(near){guard(async()=>{if(near.id==='coach'){await say([['감독','지시','목표 표시까지 움직여라. 공은 발밑에 있다. 슈팅은 X, 패스는 Z다.']]);const types=['dribble','pass','shoot'],type=types[hubRound%3];task={type,x:400,y:type==='shoot'?270:320,label:type==='shoot'?'슈팅 지점 ◆ → X':type==='pass'?'패스 지점 ◆ → Z':'콘 지점 ◆까지 드리블',lines:[]};phase='play';refresh()}else{await say([[near.name,'응원',near.id==='father'?'잔디보다 네 마음이 먼저다. 아빠는 네 편이야.':'같이 연습하자. 혼자보다 둘이 오래 뛸 수 있잖아.']]);const k=near.id==='father'?'아버지 신뢰':'멘탈';stats[k]=Math.min(100,stats[k]+1);phase='play';refresh()}});return}}
 if(!task)return;const d=Math.hypot(p.x-task.x,p.y-task.y);if(d>55){if([' ','x','z'].includes(key))notify('노란 ◆ 표시로 이동하세요 · '+Math.round(d)+'px');return}if(task.type==='hub')return;if(task.type==='returnWork'&&key===' '){guard(async()=>{await say([['김무호','독백','일을 해도 자꾸 그 빛이 생각난다.']]);task=chapters[7].tasks[0];phase='play';refresh()});return}if(task.type==='work'&&key===' '){phase='work';workStart=clock;notify('부품 검사 · 초록 구간에서 Space');return}if((task.type==='shoot'&&key==='x')||(task.type==='pass'&&key==='z')||(['talk','exit','device'].includes(task.type)&&key===' '))guard(finish)}
function update(dt){if(paused||phase==='title')return;clock+=dt;if(noticeUntil&&clock>noticeUntil){$('#notice').textContent='';noticeUntil=0}if(phase!=='play'){p.walk=false;return}let dx=(held('d')||held('arrowright')?1:0)-(held('a')||held('arrowleft')?1:0),dy=(held('s')||held('arrowdown')?1:0)-(held('w')||held('arrowup')?1:0);p.walk=!!(dx||dy);const running=held('shift')&&stamina>2;stamina=Math.max(0,Math.min(100,stamina+(running&&p.walk?-25:16)*dt));if(p.walk){const mag=Math.hypot(dx,dy),speed=running?155:100,q=move(chapters[index].map,p,dx/mag*speed*dt,dy/mag*speed*dt);p.x=q.x;p.y=q.y;p.dir=Math.abs(dx)>Math.abs(dy)?(dx<0?1:2):(dy<0?3:0);walkTime+=dt*(running?1.5:1)}if(task){const d=Math.hypot(p.x-task.x,p.y-task.y);$('#distance').textContent=`◆ 목표까지 ${Math.round(d)}px${index===4?' · '+Math.ceil(runTime)+'초':''}`;if(['walk','dribble','run'].includes(task.type)&&d<24)guard(finish);if(task.type==='run'){runTime-=dt;if(runTime<=0){runTime=45;p.x=400;p.y=445;stamina=100;notify('시간 초과 · 시작점에서 다시 도전합니다.')}}}}
function draw(){if(!art)return;g.save();g.translate(400,260);g.scale(zoom,zoom);g.translate(-400,-260);scene(g,art,tween||chapters[index].map,clock,turf);if(index===7){g.fillStyle='#ad7df3';g.shadowBlur=18;g.shadowColor='#b993ff';g.fillRect(569,184,22,16);g.shadowBlur=0;g.fillStyle='#142739';g.fillRect(573,186,14,7);label(g,'TIME',580,191,'#c4fff4',5)}if(index===4){g.fillStyle='#161c26';g.beginPath();g.moveTo(414,190);g.lineTo(425,186);g.lineTo(435,199);g.lineTo(431,217);g.lineTo(413,216);g.closePath();g.fill()}const actors=[...npcs,p].sort((a,b)=>a.y-b.y);for(const a of actors)person(g,art,a,a===p?walkTime:clock);if(['shoot','pass','dribble'].includes(task?.type)&&!shot)ball(g,p.x+12,p.y+5);if(shot){const k=Math.min(1,(clock-shot.start)/.65);ball(g,shot.fromX+(shot.toX-shot.fromX)*k,shot.fromY+(shot.toY-shot.fromY)*k-Math.sin(k*Math.PI)*40)}if(phase==='play')marker(g,task,p,clock);for(const part of particles){g.fillStyle=part.color;g.fillRect(part.x,part.y+Math.sin(clock*4+part.x)*20,3,6)}g.restore();g.fillStyle='#111a2a';g.fillRect(14,480,104,10);g.fillStyle='#91c9af';g.fillRect(16,482,stamina,6);label(g,'STAMINA',64,474,'#e0e4d2',9);if(phase==='work'){g.fillStyle='#17182bee';g.fillRect(210,195,380,90);label(g,deviceText('초록 구간에 맞춰 Space'),400,220);g.fillStyle='#796373';g.fillRect(250,240,300,16);g.fillStyle='#8bbf94';g.fillRect(355,240,120,16);g.fillStyle='#fff2b3';g.fillRect(248+(Math.sin((clock-workStart)*3)+1)*150,234,4,28)}if(flash){g.fillStyle='white';g.fillRect(0,0,800,520)}const mg=$('#mini').getContext('2d');mg.drawImage(canvas,0,0,160,104);mg.fillStyle='#fff';mg.fillRect(p.x/5-2,p.y/5-2,4,4);if(task){mg.fillStyle='#ffd984';mg.fillRect(task.x/5-2,task.y/5-2,4,4)}}
function loop(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(loop)}
function storeSave(show=true){try{localStorage.setItem('muho-rpg-v2',JSON.stringify({version:2,index,stats,hubRound}));if(show)notify('현재 챕터를 저장했습니다.')}catch{notify('저장 공간을 사용할 수 없습니다.')}}
function pause(){if(phase==='title'||phase==='video')return;paused=!paused;keys.clear();touchKeys.clear();$('#pause').hidden=!paused}
window.addEventListener('keydown',e=>{if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(e.key==='Escape'&&!e.repeat){pause();return}keys.add(e.key.toLowerCase());if(!e.repeat)action(e.key==='Enter'?'Enter':e.key.toLowerCase())});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();touchKeys.clear();if(phase!=='title'&&!paused)pause()});$('#next').onclick=next;$('#menu').onclick=pause;$('#resume').onclick=pause;$('#save').onclick=()=>storeSave();$('#restart').onclick=()=>{if(phase==='dialog'||phase==='busy'||phase==='choice'){notify('대화와 연출을 마친 뒤 다시 시작할 수 있습니다.');return}pause();guard(()=>loadChapter(index))};$('#sound').onclick=()=>$('#sound').textContent=music.toggle()?'♫ 음악 켜짐':'♫ 음악 꺼짐';
$('#new').onclick=()=>{stats=statsDefault();history=[];hubRound=0;$('#title').hidden=true;music.start();guard(()=>loadChapter(0))};$('#load').onclick=()=>{try{const s=JSON.parse(localStorage.getItem('muho-rpg-v2'));if(s?.version!==2||!Number.isInteger(s.index)||s.index<0||s.index>8||Object.keys(statsDefault()).some(k=>!Number.isFinite(s.stats[k])))throw Error();stats=s.stats;hubRound=s.hubRound||0;$('#title').hidden=true;music.start();guard(()=>loadChapter(s.index))}catch{$('#loading').textContent='새 RPG 버전의 저장 기록이 없습니다. 새로운 이야기를 시작하세요.'}};
loadArt().then(a=>{art=a;$('#new').disabled=false;$('#load').disabled=false;$('#loading').textContent='PC는 키보드 · 휴대폰은 화면 아래 조작 버튼 · 시작하면 소리가 재생됩니다.';requestAnimationFrame(loop)}).catch(()=>$('#loading').textContent='이미지를 불러오지 못했습니다. 페이지를 새로고침해 주세요.');
bindTouch($('#touch-controls'),{press:key=>{touchKeys.add(key);action(key)},release:key=>touchKeys.delete(key),clear:()=>touchKeys.clear()});
export function inspect(){return structuredClone({index,step,p,task,phase,clock,stamina,stats,hubRound,runTime,workStart})}
